import"chrome://search-engine-choice/tangible_sync_style_shared.css.js";import"chrome://resources/cr_components/localized_link/localized_link.js";import"chrome://resources/cr_elements/cr_shared_vars.css.js";import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/cr_elements/cr_dialog/cr_dialog.js";import"chrome://resources/cr_elements/cr_radio_group/cr_radio_group.js";import"chrome://resources/cr_elements/cr_radio_button/cr_radio_button.js";import"chrome://resources/cr_elements/cr_icons.css.js";import"chrome://resources/cr_elements/icons.html.js";import"chrome://resources/polymer/v3_0/iron-icon/iron-icon.js";import"./strings.m.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{getFaviconForPageURL}from"chrome://resources/js/icon.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{afterNextRender,PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./app.html.js";import{SearchEngineChoiceBrowserProxy}from"./browser_proxy.js";const SearchEngineChoiceAppElementBase=I18nMixin(PolymerElement);export class SearchEngineChoiceAppElement extends SearchEngineChoiceAppElementBase{static get is(){return"search-engine-choice-app"}static get template(){return getTemplate()}static get properties(){return{choiceList_:{type:Array,value(){return JSON.parse(loadTimeData.getString("choiceList"))}},selectedChoice_:{type:Number,value:-1,observer:"onSelectedChoiceChanged_"},isSubmitDisabled_:{type:Boolean,computed:"isSubmitButtonDisabled_(selectedChoice_)"},fakeOmniboxText_:{type:String,value:""},fakeOmniboxIconPath_:{type:String,value:""}}}connectedCallback(){super.connectedCallback();this.choiceList_.forEach((searchEngine=>{if(searchEngine.prepopulate_id===0){searchEngine.icon_path=getFaviconForPageURL(searchEngine?.url,false,"",24)}else{searchEngine.icon_path="url("+searchEngine.icon_path+")"}}));afterNextRender(this,(()=>{SearchEngineChoiceBrowserProxy.getInstance().handler.displayDialog()}))}onLinkClicked_(){this.$.infoDialog.showModal()}isSubmitButtonDisabled_(){return parseInt(this.selectedChoice_)===-1}onSubmitClicked_(){SearchEngineChoiceBrowserProxy.getInstance().handler.handleSearchEngineChoiceSelected(parseInt(this.selectedChoice_))}onInfoDialogButtonClicked_(){this.$.infoDialog.close()}onSelectedChoiceChanged_(selectedChoice){if(parseInt(selectedChoice)===-1){return}const choice=this.choiceList_.find((elem=>elem.prepopulate_id===parseInt(selectedChoice)));const searchEngineOmnibox=this.$.searchEngineOmnibox;const dummyOmnibox=this.$.dummyOmnibox;const fakeOmniboxText=this.i18n("fakeOmniboxText",choice?.name);const fakeOmniboxIconPath=choice?.icon_path;const handleFadeOutFinished=event=>{if(event.animationName==="fade-out-animation"){searchEngineOmnibox.classList.remove("fade-out-animation");this.fakeOmniboxText_=fakeOmniboxText;this.fakeOmniboxIconPath_=fakeOmniboxIconPath;window.requestAnimationFrame((function(){searchEngineOmnibox.classList.add("fade-in-animation")}))}else if(event.animationName==="fade-in-animation"){if(!dummyOmnibox.classList.contains("hidden")){dummyOmnibox.classList.add("hidden")}}};const handleAnimationStart=event=>{if(event.animationName==="fade-out-animation"){dummyOmnibox.classList.remove("hidden")}};searchEngineOmnibox.addEventListener("animationend",handleFadeOutFinished);searchEngineOmnibox.addEventListener("animationstart",handleAnimationStart);if(searchEngineOmnibox.classList.contains("fade-in-animation")){searchEngineOmnibox.classList.remove("fade-in-animation");window.requestAnimationFrame((function(){searchEngineOmnibox.classList.add("fade-out-animation")}))}else{this.fakeOmniboxText_=fakeOmniboxText;this.fakeOmniboxIconPath_=fakeOmniboxIconPath;searchEngineOmnibox.classList.add("fade-in-animation")}}}customElements.define(SearchEngineChoiceAppElement.is,SearchEngineChoiceAppElement);